of st[k] === 'object' && st[k] !== null ? (st[k] as any).描述 || k : k)).slice(0, 3);\n});\n</script>\n\n<style scoped>\n.unit-card {\n  display: flex;\n  gap: 8px;\n  background: #fbf3e2;\n  border: 1px solid rgba(160, 120, 64, 0.4);\n  border-radius: 4px;\n  padding: 6px;\n  transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;\n}\n.unit-card:hover {\n  background: #f6ead0;\n  border-color: #c4a050;\n}\n.unit-card.turn {\n  border: 2px solid #d4af37;\n  box-shadow: 0 0 6px rgba(212, 175, 55, 0.35);\n  background: #f9edc8;\n}\n\n.unit-avatar {\n  position: relative;\n  flex-shrink: 0;\n  width: 42px;\n  height: 42px;\n}\n.avatar-img {\n  width: 42px;\n  height: 42px;\n  border-radius: 4px;\n  object-fit: cover;\n  border: 1px solid #a07840;\n  background: #f0e2c0;\n}\n.avatar-fallback {\n  width: 42px;\n  height: 42px;\n  border-radius: 4px;\n  border: 1px solid #a07840;\n  background: linear-gradient(135deg, #d9c08a, #b09050);\n  color: #5a3a08;\n  font-size: 1.2em;\n  font-weight: 800;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.avatar-badge {\n  position: absolute;\n  right: -4px;\n  bottom: -4px;\n  font-size: 0.58em;\n  padding: 1px 5px;\n  border-radius: 8px;\n  color: #fff;\n  border: 1px solid rgba(255, 255, 255, 0.6);\n}\n.avatar-badge.ally {\n  background: #3a6a2a;\n}\n.avatar-badge.enemy {\n  background: #8a2a1a;\n}\n.avatar-badge.spirit {\n  background: linear-gradient(135deg, #6a3a9a, #4a1e6a);\n}\n\n.unit-info {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n}\n.unit-name {\n  font-size: 0.88em;\n  font-weight: 800;\n  color: #3a2718;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.unit-name.dead {\n  color: #8a2020;\n  text-decoration: line-through;\n}\n\n.bar-row {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n.bar-label {\n  flex-shrink: 0;\n  font-size: 0.6em;\n  font-weight: 800;\n  color: #6a5430;\n  width: 20px;\n}\n.bar-b